package com.rescuefarm.ui.engagement;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.fragment.app.Fragment;import androidx.lifecycle.ViewModelProvider;import com.google.firebase.auth.FirebaseAuth;import com.rescuefarm.R;import com.rescuefarm.domain.model.Review;import java.util.*;
public class ReviewFragment extends Fragment{private EngagementViewModel vm;private EditText order,item,rating,content,images;private LinearLayout list;private String productId="",uid="";@Nullable public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup p,@Nullable Bundle s){return i.inflate(R.layout.fragment_reviews,p,false);}@Override public void onViewCreated(@NonNull View v,@Nullable Bundle s){productId=getArguments()==null?"":getArguments().getString("productId","");uid=FirebaseAuth.getInstance().getCurrentUser()==null?"":FirebaseAuth.getInstance().getCurrentUser().getUid();order=v.findViewById(R.id.reviewOrderId);item=v.findViewById(R.id.reviewOrderItemId);rating=v.findViewById(R.id.reviewRating);content=v.findViewById(R.id.reviewContent);images=v.findViewById(R.id.reviewImages);list=v.findViewById(R.id.reviewContainer);vm=new ViewModelProvider(this,new EngagementViewModelFactory(requireContext())).get(EngagementViewModel.class);vm.reviews().observe(getViewLifecycleOwner(),this::render);vm.getState().observe(getViewLifecycleOwner(),x->{if(x.getStatus()==EngagementState.Status.ERROR||x.getStatus()==EngagementState.Status.SUCCESS)Toast.makeText(requireContext(),x.getMessage(),Toast.LENGTH_SHORT).show();});v.findViewById(R.id.saveReviewButton).setOnClickListener(x->save());vm.refreshReviews(productId);}private void save(){try{List<String>urls=new ArrayList<>();for(String x:images.getText().toString().split("[,\\n]"))if(!x.trim().isEmpty())urls.add(x.trim());Review r=Review.create(uid,productId,text(order),text(item),Integer.parseInt(text(rating)),text(content),urls,new Date());vm.saveReview(r,false);}catch(Exception e){Toast.makeText(requireContext(),e.getMessage(),Toast.LENGTH_LONG).show();}}private void render(List<Review>xs){list.removeAllViews();if(xs==null)return;for(Review r:xs){TextView t=new TextView(requireContext());t.setText(getString(R.string.review_row_format,r.getRating(),r.getContent()));list.addView(t);}}private String text(EditText e){return e.getText().toString().trim();}}
